using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;
using ChurnPredictor.Models;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var data = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');

var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

var lookupData = new[] {
    new LookupInput { Churned = "Yes", Label = true },
    new LookupInput { Churned = "No",  Label = false }
};
var lookupView = mlContext.Data.LoadFromEnumerable(lookupData);

var pipeline = mlContext.Transforms.Conversion.MapValue(
        outputColumnName: "Label",
        lookupMap: lookupView,
        lookupKeyColumn: lookupView.Schema["Churned"],
        lookupValueColumn: lookupView.Schema["Label"],
        inputColumnName: "Churned")
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
    .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
    .Append(mlContext.BinaryClassification.Trainers.FastTree());

var model = pipeline.Fit(split.TrainSet);

var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
Console.WriteLine($"AUC: {metrics.AreaUnderRocCurve:F4}");
Console.WriteLine($"F1:  {metrics.F1Score:F4}");

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
    .FromModel(model, mlContext);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnPrediction> pool, PredictRequest request) =>
{
    var input = new ChurnInput
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region ?? string.Empty,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = pool.Predict(input);

    return Results.Ok(new
    {
        predictedChurn = prediction.PredictedLabel,
        probability = prediction.Probability,
        score = prediction.Score
    });
});

app.Run();

public class LookupInput
{
    public string Churned { get; set; } = string.Empty;
    public bool Label { get; set; }
}

public record PredictRequest(float Age, float Income, string? Region, float PurchaseHistory);

